    private void addQuestion(Question question) {
        ContentValues contentValues = new ContentValues();
        contentValues.put(QuizContract.QuestionTable.COLUMN_QUESTION, question.getQuestion());
        contentValues.put(QuizContract.QuestionTable.COLUMN_OPTION1, question.getOption1());
        contentValues.put(QuizContract.QuestionTable.COLUMN_OPTION2, question.getOption2());
        contentValues.put(QuizContract.QuestionTable.COLUMN_OPTION3, question.getOption3());
        contentValues.put(QuizContract.QuestionTable.COLUMN_OPTION4, question.getOption4());
        contentValues.put(QuizContract.QuestionTable.COLUMN_ANSWER_NR, Integer.valueOf(question.getAnsewer()));
        contentValues.put(QuizContract.QuestionTable.COLUMN_Unit, Integer.valueOf(question.getUnit()));
        contentValues.put(QuizContract.QuestionTable.COLUMN_TYPE, question.getType());
        this.sqLiteDatabase.insert(QuizContract.QuestionTable.TABLENAME, null, contentValues);
    }

    public ArrayList<Question> getAllQuestion(int unit, String type) {
        ArrayList<Question> arrayList = new ArrayList<>();
        SQLiteDatabase readableDatabase = getReadableDatabase();
        this.sqLiteDatabase = readableDatabase;
        Cursor rawQuery = readableDatabase.rawQuery("SELECT * FROM quiz_questions WHERE unit = '" + unit + "' and type = '" + type + "' ORDER BY RANDOM() LIMIT 10", null);
        if (rawQuery.moveToFirst()) {
            do {
                Question question = new Question();
                question.setQuestion(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_QUESTION)));
                question.setOption1(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_OPTION1)));
                question.setOption2(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_OPTION2)));
                question.setOption3(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_OPTION3)));
                question.setOption4(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_OPTION4)));
                question.setAnsewer(rawQuery.getInt(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_ANSWER_NR)));
                question.setUnit(rawQuery.getInt(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_Unit)));
                question.setType(rawQuery.getString(rawQuery.getColumnIndex(QuizContract.QuestionTable.COLUMN_TYPE)));
                arrayList.add(question);
            } while (rawQuery.moveToNext());
        }
        rawQuery.close();
        return arrayList;
    }
